// GABARIT UNIQUE de tout ce qu'UniFlow envoie hors de l'application.
//
// Pourquoi un sous-workflow plutôt que du HTML dans chaque workflow métier :
// trois Uni qui ne se ressemblent pas se voient immédiatement, et une correction
// de rendu email (Outlook desktop ignore border-radius et le WebP, Gmail coupe
// les messages au-delà d'environ 102 Ko) devrait sinon être reprise trois fois.
//
// Entrée attendue : { subject, preheader, title, salutation, paragraphs:[],
//                    bullets:[], cta:{label,url}, note }
// Sortie           : { subject, preheader, html, textPlain }
//
// Le HTML ne DOIT jamais sortir vers l'application elle-même : le chat web rend
// le texte échappé (MessagingPage.tsx:377) et les bulles Flutter sont des
// widgets Text() — un étudiant lirait les balises. Réservé à Gmail et au PDF.

const HOST = 'https://uniflow.kernelforge.codes'
// PNG et non le .webp voisin : Outlook desktop ne sait pas décoder WebP, et le
// pied de page disparaîtrait chez une partie des enseignants.
const AVATAR = `${HOST}/assistant/uni-avatar.png`

// Teintes reprises de src/components/assistant/UniAssistant.tsx (#1e3a8a bleu,
// #0d9488 turquoise, #111827 texte, #e5e7eb filet, #eff3ff fond) : le message
// doit avoir la tête du produit, pas celle d'un mail transactionnel générique.
const C = { bleu: '#1e3a8a', turquoise: '#0d9488', texte: '#111827', filet: '#e5e7eb', fond: '#eff3ff', fondClair: '#dce5fd' }

// Tout ce qui vient d'Appwrite (le nom du compte, saisi par la personne qui
// s'inscrit) passe par ici. Sans échappement, un profil nommé
// « <img src=x onerror=alert(1)> » deviendrait du script exécuté dans la
// messagerie du destinataire.
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]))

const input = $input.first().json || {}
const paragraphs = Array.isArray(input.paragraphs) ? input.paragraphs : []
const bullets = Array.isArray(input.bullets) ? input.bullets : []
const cta = input.cta && input.cta.label && input.cta.url ? input.cta : null
const title = input.title || 'UniFlow'

const row = (inner, pad = '0 32px') => `<tr><td style="padding:${pad};font:15px/1.6 -apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:${C.texte};">${inner}</td></tr>`

const bulletRows = bullets.length
  ? row(`<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">${bullets.map((b) => `<tr><td valign="top" width="18" style="padding:2px 0;color:${C.turquoise};font:15px/1.6 Arial,sans-serif;">•</td><td style="padding:2px 0 2px 8px;color:${C.texte};font:15px/1.6 Arial,sans-serif;">${esc(b)}</td></tr>`).join('')}</table>`)
  : ''

const ctaRow = cta
  ? row(`<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="${C.bleu}" style="background:${C.bleu};border-radius:10px;">&nbsp;<a href="${esc(cta.url)}" style="padding:11px 22px;display:inline-block;color:#ffffff;font:600 15px/1.4 Arial,sans-serif;text-decoration:none;">${esc(cta.label)}</a>&nbsp;</td></tr></table>`, '8px 32px 24px')
  : ''

const noteRow = input.note
  ? row(`<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr><td bgcolor="${C.fond}" style="background:${C.fond};border-left:3px solid ${C.turquoise};padding:12px 16px;color:${C.bleu};font:14px/1.6 Arial,sans-serif;">${esc(input.note)}</td></tr></table>`, '8px 32px 24px')
  : ''

// Pied de page : la photo d'Uni est une exigence du propriétaire (2026-09-25).
// Liens en routes hash — le site est en React Router hash-based, /#/login ; une
// URL « /login » renverrait un 404 et le lien semblerait cassé.
const footer = `
  <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin-top:28px;">
    <tr><td style="padding:0;border-top:1px solid ${C.filet};">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">
        <tr>
          <td width="76" valign="middle" style="padding:20px 0 0 32px;">
            <img src="${AVATAR}" width="60" height="60" alt="Uni" style="display:block;width:60px;height:60px;">
          </td>
          <td valign="middle" style="padding:20px 32px 0 14px;font:13px/1.7 Arial,sans-serif;color:${C.texte};">
            <strong style="color:${C.bleu};">Uni</strong> — l'assistant de UniFlow<br>
            KERNEL FORGE · Université de Yaoundé I, Faculté des Sciences<br>
            <a href="${HOST}/#/login" style="color:${C.turquoise};text-decoration:none;">Se connecter</a>
            &nbsp;·&nbsp;
            <a href="https://wa.me/237657635644" style="color:${C.turquoise};text-decoration:none;">Écrire à l'équipe</a>
          </td>
        </tr>
      </table>
    </td></tr>
  </table>`

const html = `<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title></head>
<body style="margin:0;padding:0;background:#f5f7fb;">
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;">${esc(input.preheader || '')}</div>
  <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:#f5f7fb;">
    <tr><td align="center" style="padding:24px 12px;">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;background:#ffffff;border:1px solid ${C.filet};border-radius:14px;overflow:hidden;">
        <tr><td bgcolor="${C.bleu}" style="background:${C.bleu};padding:22px 32px;">
          <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr>
            <td style="font:700 19px/1.2 Arial,sans-serif;color:#ffffff;">UniFlow</td>
            <td align="right" style="font:12px/1.2 Arial,sans-serif;color:${C.fondClair};letter-spacing:.06em;text-transform:uppercase;">KERNEL FORGE</td>
          </tr></table>
        </td></tr>
        ${row(`<h1 style="margin:26px 0 6px;font:600 21px/1.3 Arial,sans-serif;color:${C.bleu};">${esc(title)}</h1>`, '0 32px')}
        ${input.salutation ? row(esc(input.salutation)) : ''}
        ${paragraphs.map((p) => row(esc(p))).join('')}
        ${bulletRows}
        ${ctaRow}
        ${noteRow}
        ${footer}
        <tr><td style="padding:14px 32px 22px;font:11px/1.6 Arial,sans-serif;color:#6b7280;border-top:1px solid ${C.filet};">Vous recevez ce message parce qu'un compte UniFlow a été créé avec cette adresse. Les offres payantes se règlent par WhatsApp, jamais par carte dans l'application.</td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`

const textPlain = [
  input.subject || title,
  '',
  input.salutation || '',
  ...paragraphs,
  ...bullets.map((b) => `- ${b}`),
  cta ? `${cta.label} : ${cta.url}` : '',
  input.note ? `Note : ${input.note}` : '',
  '',
  'Uni — l’assistant de UniFlow · KERNEL FORGE · Université de Yaoundé I',
  `${HOST}/#/login`,
].filter((line) => line !== '').join('\n')

if (!input.subject) throw new Error('GABARIT_ENTREE: « subject » est obligatoire')

return [{ json: { subject: String(input.subject), preheader: String(input.preheader || ''), html, textPlain } }]
